<?php if($r['documents']):?><p><strong>Documents :</strong> <?php foreach($r['documents'] as$d):?><a href="<?=e(base_url('documents/'.$d['id']))?>"><?=e($d['display_code'].' '.$d['document_number'].' ['.$d['status'].']')?></a> <?php endforeach;?></p><?php endif;?>
<?php if($r['nonconformities']):?><div class="alert alert-warning"><strong>Non-conformités :</strong> <?php foreach($r['nonconformities'] as$n):?><?=e($n['reference'].' ['.$n['status'].'] — '.($n['description']?:'Sans commentaire'))?> <?php endforeach;?></div><?php endif;?>
<?php if($r['movements']):?><details><summary>Mouvements de stock (<?=count($r['movements'])?>)</summary><div class="table-responsive"><table class="enterprise-table" data-datatable="false"><thead><tr><th>Mouvement</th><th>Quantité enregistrée</th><th>Date</th><th>Stock avant → après</th></tr></thead><tbody><?php foreach($r['movements'] as$m):?><tr><td><?=e($m['movement_type'])?></td><td><?=e($m['quantity_kg']??$m['quantity']??'')?></td><td><?=e($m['movement_date'])?></td><td><?=e(($m['stock_before_kg']??$m['physical_before_kg']??'').' → '.($m['stock_after_kg']??$m['physical_after_kg']??''))?></td></tr><?php endforeach;?></tbody></table></div></details><?php endif;?>
<?php if($r['corrections']):?><div class="alert alert-warning"><strong>Annulation/correction :</strong> <?php foreach($r['corrections'] as$c):?><?=e($c['request_number'].' '.$c['status'].' '.($c['reversal_number']?:'').' — '.$c['reason'])?> <?php endforeach;?></div><?php endif;?>